('music', 3, 'Which band released "Songs for the Deaf" in 2002?', 'Queens of the Stone Age', ARRAY['Foo Fighters', 'Audioslave', 'System of a Down'], 'en', true, 'Songs for the Deaf by Queens of the Stone Age features Dave Grohl on drums.'),
('music', 3, 'Which singer released "Back to Black" in 2006?', 'Amy Winehouse', ARRAY['Adele', 'Duffy', 'Lily Allen'], 'en', true, 'Back to Black by Amy Winehouse won multiple Grammy Awards and became a modern classic.'),
('music', 3, 'Which band released "The Joshua Tree" in 1987?', 'U2', ARRAY['REM', 'The Cure', 'Depeche Mode'], 'en', true, 'The Joshua Tree by U2 is one of the best-selling albums ever with over 25 million copies sold.'),
('music', 3, 'Which composer wrote the "New World Symphony"?', 'Antonin Dvorak', ARRAY['Bedrich Smetana', 'Leos Janacek', 'Gustav Mahler'], 'en', true, 'The New World Symphony was composed by Dvorak in 1893 during his stay in the United States.'),
('music', 3, 'Which album by Kendrick Lamar won the Pulitzer Prize?', 'DAMN.', ARRAY['To Pimp a Butterfly', 'good kid, m.A.A.d city', 'Section.80'], 'en', true, 'DAMN. by Kendrick Lamar won the 2018 Pulitzer Prize for Music, a first for hip-hop.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('music', 4, 'Who produced Michael Jackson''s "Thriller" album?', 'Quincy Jones', ARRAY['Phil Collins', 'Nile Rodgers', 'George Martin'], 'en', true, 'Quincy Jones produced Thriller, the best-selling album of all time.'),
('music', 4, 'Which Kraftwerk album is a pioneer of electronic music?', 'Autobahn', ARRAY['Computer World', 'Trans-Europe Express', 'The Man-Machine'], 'en', true, 'Autobahn (1974) by Kraftwerk is a foundational album of electronic music.'),
('music', 4, 'Which composer wrote "Pictures at an Exhibition"?', 'Modest Mussorgsky', ARRAY['Nikolai Rimsky-Korsakov', 'Alexander Borodin', 'Cesar Cui'], 'en', true, 'Pictures at an Exhibition was composed by Mussorgsky in 1874 and later orchestrated by Ravel.'),
('music', 4, 'Which trumpeter recorded "Kind of Blue"?', 'Miles Davis', ARRAY['Chet Baker', 'Dizzy Gillespie', 'Freddie Hubbard'], 'en', true, 'Kind of Blue by Miles Davis, released in 1959, is the best-selling jazz album ever.'),
('music', 4, 'Which band released "Loveless", the shoegaze masterpiece?', 'My Bloody Valentine', ARRAY['Slowdive', 'Ride', 'Cocteau Twins'], 'en', true, 'Loveless by My Bloody Valentine, released in 1991, defined the shoegaze genre.'),
('music', 4, 'What alternative guitar tuning is called "Open G"?', 'D-G-D-G-B-D', ARRAY['D-A-D-F#-A-D', 'E-A-C#-E-A-E', 'C-G-C-G-C-E'], 'en', true, 'Open G tuning (DGDGBD) is famously used by Keith Richards of The Rolling Stones.'),
('music', 4, 'Which Joy Division album was released after Ian Curtis''s death?', 'Closer', ARRAY['Unknown Pleasures', 'Still', 'Substance'], 'en', true, 'Closer was released in July 1980, two months after Ian Curtis''s suicide in May 1980.'),
('music', 4, 'Which rapper released "The Marshall Mathers LP" in 2000?', 'Eminem', ARRAY['Jay-Z', 'DMX', 'Dr. Dre'], 'en', true, 'The Marshall Mathers LP by Eminem sold over 35 million copies worldwide.'),
('music', 4, 'Which composer wrote "Messiah" containing the famous "Hallelujah"?', 'Handel', ARRAY['Bach', 'Vivaldi', 'Haydn'], 'en', true, 'Messiah by George Frideric Handel, composed in 1741, contains the famous Hallelujah chorus.'),
('music', 4, 'What is the vocal technique used in yodeling called?', 'Yodel', ARRAY['Vibrato', 'Falsetto', 'Belting'], 'en', true, 'Yodeling rapidly alternates between the chest voice and head voice registers.'),
('music', 4, 'Which Radiohead album was released in 2000?', 'Kid A', ARRAY['Amnesiac', 'Hail to the Thief', 'OK Computer'], 'en', true, 'Kid A by Radiohead marked a departure from traditional rock into electronic experimentation.'),
('music', 4, 'Which pianist is known for "Transcendental Etudes"?', 'Franz Liszt', ARRAY['Frederic Chopin', 'Robert Schumann', 'Johannes Brahms'], 'en', true, 'Liszt''s Transcendental Etudes are among the most technically demanding piano pieces ever written.'),
('music', 4, 'Which Russian composer wrote "Peter and the Wolf"?', 'Sergei Prokofiev', ARRAY['Dmitri Shostakovich', 'Igor Stravinsky', 'Sergei Rachmaninoff'], 'en', true, 'Peter and the Wolf by Prokofiev was composed in 1936 to introduce children to orchestral instruments.'),
('music', 4, 'Which post-punk band released "Disintegration" in 1989?', 'The Cure', ARRAY['Depeche Mode', 'Siouxsie and the Banshees', 'Bauhaus'], 'en', true, 'Disintegration by The Cure is considered their finest album, featuring Lovesong and Pictures of You.'),
('music', 4, 'What musical interval separates C and F#?', 'Tritone', ARRAY['Perfect fifth', 'Augmented fourth', 'Minor sixth'], 'en', true, 'The tritone is an interval of 6 semitones, historically called "diabolus in musica".'),
('music', 4, 'Which French band released "Moon Safari" in 1998?', 'Air', ARRAY['Daft Punk', 'Phoenix', 'M83'], 'en', true, 'Moon Safari by Air is a landmark album of French electronic music.'),
('music', 4, 'Which jazz musician co-invented bebop with Charlie Parker?', 'Dizzy Gillespie', ARRAY['Miles Davis', 'Thelonious Monk', 'Kenny Clarke'], 'en', true, 'Dizzy Gillespie and Charlie Parker were the primary creators of bebop in the 1940s.'),
('music', 4, 'Which Bjork album contains "Hyperballad"?', 'Post', ARRAY['Homogenic', 'Debut', 'Vespertine'], 'en', true, 'Hyperballad appears on Bjork''s album Post, released in 1995.'),
('music', 4, 'Which composer wrote the "Goldberg Variations"?', 'Johann Sebastian Bach', ARRAY['George Frideric Handel', 'Antonio Vivaldi', 'Domenico Scarlatti'], 'en', true, 'The Goldberg Variations by Bach, composed around 1741, are a pinnacle of keyboard music.'),
('music', 4, 'Which band released "Remain in Light" in 1980?', 'Talking Heads', ARRAY['Blondie', 'Devo', 'Wire'], 'en', true, 'Remain in Light by Talking Heads blends rock, African funk, and electronic music.'),
('music', 4, 'Which saxophonist recorded "A Love Supreme" in 1965?', 'John Coltrane', ARRAY['Sonny Rollins', 'Charlie Parker', 'Cannonball Adderley'], 'en', true, 'A Love Supreme by John Coltrane is a four-part spiritual suite considered a jazz masterpiece.'),
('music', 4, 'Which Massive Attack album is considered the founder of trip-hop?', 'Blue Lines', ARRAY['Mezzanine', 'Protection', 'Heligoland'], 'en', true, 'Blue Lines (1991) by Massive Attack is generally considered the first trip-hop album.'),
('music', 4, 'Which U2 album was released in 1991 and marked a sonic shift?', 'Achtung Baby', ARRAY['Zooropa', 'The Joshua Tree', 'Pop'], 'en', true, 'Achtung Baby marked a turning point for U2 with a more electronic and experimental sound.'),
('music', 4, 'Which Czech composer wrote the "New World Symphony"?', 'Antonin Dvorak', ARRAY['Bedrich Smetana', 'Leos Janacek', 'Bohuslav Martinu'], 'en', true, 'Dvorak composed his ninth symphony during his stay in America in 1893.'),
('music', 4, 'Which rapper released "Madvillainy" as MF DOOM?', 'Daniel Dumile', ARRAY['Otis Jackson Jr.', 'Jarobi White', 'Keith Elam'], 'en', true, 'MF DOOM, whose real name was Daniel Dumile, created Madvillainy with Madlib in 2004.'),
('music', 4, 'Which French composer wrote "Daphnis and Chloe"?', 'Maurice Ravel', ARRAY['Claude Debussy', 'Camille Saint-Saens', 'Paul Dukas'], 'en', true, 'Daphnis and Chloe is a ballet by Ravel composed in 1912 for the Ballets Russes.'),
('music', 4, 'Which album by Serge Gainsbourg is considered his masterpiece?', 'Histoire de Melody Nelson', ARRAY['L''Homme a tete de chou', 'Love on the Beat', 'Aux armes et caetera'], 'en', true, 'Histoire de Melody Nelson (1971) is a concept album considered a masterpiece of French music.'),
('music', 4, 'Which band released "In the Court of the Crimson King" in 1969?', 'King Crimson', ARRAY['Genesis', 'Yes', 'Emerson Lake and Palmer'], 'en', true, 'In the Court of the Crimson King is King Crimson''s debut album and a cornerstone of progressive rock.'),
('music', 4, 'Which Radiohead album pioneered their electronic direction?', 'Kid A', ARRAY['OK Computer', 'Amnesiac', 'Hail to the Thief'], 'en', true, 'Kid A (2000) represented Radiohead''s shift from guitar rock to electronic and experimental music.'),
('music', 4, 'Which composer wrote "The Rite of Spring"?', 'Igor Stravinsky', ARRAY['Claude Debussy', 'Maurice Ravel', 'Sergei Prokofiev'], 'en', true, 'The Rite of Spring by Stravinsky premiered in 1913 and caused a riot due to its revolutionary style.');
INSERT INTO questions (category, difficulty, question_text, correct_answer, wrong_answers, language, is_active, explanation) VALUES
('music', 5, 'In what key is Beethoven''s "Moonlight Sonata" written?', 'C-sharp minor', ARRAY['A minor', 'E minor', 'B minor'], 'en', true, 'Beethoven''s Piano Sonata No. 14, the Moonlight Sonata, is written in C-sharp minor.'),
('music', 5, 'Which composer wrote the "Concerto for Orchestra" in 1943?', 'Bela Bartok', ARRAY['Sergei Prokofiev', 'Dmitri Shostakovich', 'Paul Hindemith'], 'en', true, 'Bartok''s Concerto for Orchestra is one of his last works, composed during his exile in the USA.'),
('music', 5, 'What is the name of the first chord in Wagner''s "Tristan und Isolde"?', 'Tristan chord', ARRAY['Neapolitan chord', 'Augmented chord', 'German sixth chord'], 'en', true, 'The Tristan chord (F-B-D#-G#) is an ambiguous chord that revolutionized harmony.'),
('music', 5, 'Which Talk Talk album is considered a precursor to post-rock?', 'Spirit of Eden', ARRAY['Laughing Stock', 'The Colour of Spring', 'It''s My Life'], 'en', true, 'Spirit of Eden (1988) by Talk Talk paved the way for post-rock with its experimental approach.'),
('music', 5, 'What tuning system divides the octave into 12 equal semitones?', 'Equal temperament', ARRAY['Pythagorean tuning', 'Meantone temperament', 'Just intonation'], 'en', true, 'Equal temperament divides the octave into 12 equal intervals of approximately 100 cents each.'),
('music', 5, 'Which composer wrote "Gruppen" for three orchestras?', 'Karlheinz Stockhausen', ARRAY['Pierre Boulez', 'Luigi Nono', 'Iannis Xenakis'], 'en', true, 'Gruppen (1957) by Stockhausen is a serial work for three orchestras placed around the audience.'),
('music', 5, 'Which Can album is considered a krautrock masterpiece?', 'Tago Mago', ARRAY['Ege Bamyasi', 'Future Days', 'Soundtracks'], 'en', true, 'Tago Mago (1971) by Can is a foundational double album of the krautrock genre.'),
('music', 5, 'What is the composition technique using a series of all 12 chromatic notes?', 'Twelve-tone technique', ARRAY['Total serialism', 'Free atonality', 'Spectral music'], 'en', true, 'The twelve-tone technique, invented by Schoenberg, uses all 12 chromatic notes in a fixed order.'),
('music', 5, 'Which French composer founded IRCAM?', 'Pierre Boulez', ARRAY['Olivier Messiaen', 'Henri Dutilleux', 'Iannis Xenakis'], 'en', true, 'Pierre Boulez founded IRCAM (Institute for Research and Coordination in Acoustics/Music) in 1977.'),
('music', 5, 'Which Fela Kuti album is emblematic of Afrobeat?', 'Zombie', ARRAY['Expensive Shit', 'Gentleman', 'Confusion'], 'en', true, 'Zombie (1977) by Fela Kuti is a political album criticizing the Nigerian military.'),
('music', 5, 'Who invented the twelve-tone composition system?', 'Arnold Schoenberg', ARRAY['Alban Berg', 'Anton Webern', 'Paul Hindemith'], 'en', true, 'Schoenberg developed the twelve-tone system in the early 1920s to organize atonal music.'),
('music', 5, 'What interval was called "diabolus in musica" in the Middle Ages?', 'The tritone', ARRAY['The minor second', 'The major seventh', 'The minor ninth'], 'en', true, 'The tritone, an interval of three whole tones, was considered dissonant and dangerous in the Middle Ages.'),
('music', 5, 'Which American composer wrote "4''33"?', 'John Cage', ARRAY['Steve Reich', 'Philip Glass', 'Terry Riley'], 'en', true, '4''33" by John Cage (1952) is a silent piece that questions the very nature of music.'),
('music', 5, 'What is the exact frequency of middle C (C4) in equal temperament?', '261.63 Hz', ARRAY['256 Hz', '264 Hz', '270 Hz'], 'en', true, 'In equal temperament with A4 = 440 Hz, middle C (C4) vibrates at exactly 261.63 Hz.'),
('music', 5, 'Which composer wrote "Atmospheres", used in "2001: A Space Odyssey"?', 'Gyorgy Ligeti', ARRAY['Krzysztof Penderecki', 'Witold Lutoslawski', 'Iannis Xenakis'], 'en', true, 'Atmospheres (1961) by Ligeti uses micropolyphony and was featured in Kubrick''s 2001.'),
('music', 5, 'What is the name of the African rhythmic process based on interlocking patterns?', 'Polyrhythm', ARRAY['Homophony', 'Isorhythm', 'Heterophony'], 'en', true, 'African polyrhythm superimposes multiple different rhythmic patterns to create complex textures.'),
('music', 5, 'Which composer wrote "Le Marteau sans maitre"?', 'Pierre Boulez', ARRAY['Olivier Messiaen', 'Karlheinz Stockhausen', 'Luciano Berio'], 'en', true, 'Le Marteau sans maitre (1955) by Boulez is a serial work set to poems by Rene Char.'),
('music', 5, 'Which Autechre album is considered an IDM classic?', 'Tri Repetae', ARRAY['Amber', 'LP5', 'Confield'], 'en', true, 'Tri Repetae (1995) by Autechre is a key album in IDM (Intelligent Dance Music).'),
('music', 5, 'Which Indian music system is based on melodic scales with specific performance rules?', 'Raga', ARRAY['Tala', 'Shruti', 'Swara'], 'en', true, 'The raga system defines melodic scales with specific rules of interpretation in Indian classical music.'),
('music', 5, 'Which Magma album founded the zeuhl genre?', 'Mekanik Destruktiw Kommandoh', ARRAY['Kohntarkosz', 'Wurdah Itah', 'Udu Wudu'], 'en', true, 'Mekanik Destruktiw Kommandoh (1973) by Magma defined the zeuhl genre, a unique style in music.');
